// The two scrapers return different field names, so nothing downstream can compare them until
// the shape matches. Stamp the platform on each row while we still know which branch it came
// from, and normalise rating and text to one name each.
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const isPlay = j.appId !== undefined || j.reviewId !== undefined;
  const text = (j.text || j.review || j.content || j.body || '').toString().trim();
  if (!text) continue;
  out.push({ json: {
    platform: isPlay ? 'Android' : 'iPhone',
    rating: Number(j.score != null ? j.score : (j.rating || 0)),
    text,
    id: String(j.reviewId || j.id || text.slice(0, 40)),
    date: j.date || j.updated || null,
  } });
}
return out;

// The point of the workflow: not a list of complaints, but which ones are LOPSIDED.
// A theme with 14 mentions on Android and 1 on iPhone is almost certainly a platform bug.
// One split evenly is a product decision. Counting per platform is what separates them, and it
// can only happen once every row is labelled - which is why it sits here and not inside a loop.
const rows = $input.all();
const seen = $('Skip reviews seen last week').all();
const tally = {};
for (let i = 0; i < rows.length; i++) {
  const theme = (rows[i].json.text || '').toString().trim().toLowerCase();
  if (!theme || theme === 'none') continue;
  // the chain preserves order, so row i corresponds to input i
  const platform = seen[i] ? seen[i].json.platform : 'unknown';
  if (!tally[theme]) tally[theme] = { theme, Android: 0, iPhone: 0 };
  if (tally[theme][platform] !== undefined) tally[theme][platform] += 1;
}
const out = Object.keys(tally).map((k) => {
  const t = tally[k];
  const total = t.Android + t.iPhone;
  const skew = total ? Math.abs(t.Android - t.iPhone) / total : 0;
  return { json: {
    theme: t.theme,
    android: t.Android,
    iphone: t.iPhone,
    total,
    // 1.0 means it only ever happens on one platform, 0 means both equally
    lopsidedness: Number(skew.toFixed(2)),
    verdict: skew >= 0.7 ? 'looks platform-specific' : 'affects both',
    week: new Date().toISOString().slice(0, 10),
  } };
});
out.sort((a, b) => b.json.total - a.json.total);
return out;
